3	  %
4	  %   X = kalman_update_fast(Z, model)
5	  %
6	  %   Drop-in replacement for KALMAN_UPDATE (CVT estimator v2.1.0) with the
7	  %   same inputs and outputs:
8	  %
9	  %   Z      N-by-m matrix; row k is the measurement z_k (columns beyond m,
10	  %          the number of rows of H, are ignored, as in the original).
11	  %   model  struct with fields F (n-by-n), Q (n-by-n), H (m-by-n), R (m-by-m),
12	  %          x0 (n-by-1), P0 (n-by-n).
13	  %   X      N-by-n matrix; row k is the posterior state estimate after step k.
14	  %
15	  % Same recursion as the original, per CVT-EST-001 Rev B section 4:
16	  %     x = F x;            P = F P F' + Q
17	  %     y = z - H x;        S = H P H' + R
18	  %     K = P H' inv(S);    x = x + K y;   P = (I - K H) P
19	  %
20	  % Output is bit-identical to KALMAN_UPDATE for any model with m == 2. Two
21	  % things make it fast without changing a single bit:
22	  %
23	  % 1. Exact-order vectorized products. Every product C = A*B is accumulated as
24	  %        C = 0;  for p = 1:inner,  C = C + A(:,p) .* B(p,:);  end
25	  %    This is the same order and starting value as the original's scalar
26	  %    loops (s = 0; s = s + A(i,p)*B(p,j)), but a whole matrix at a time, and
27	  %    each term is one correctly rounded element-wise multiply. The built-in
28	  %    matrix multiply is deliberately not used, because BLAS adds the terms in
29	  %    a different order and its result is not bit-identical. These loops are
30	  %    written inline, because function-call overhead would otherwise dominate.
31	  %
32	  % 2. Periodic-gain shortcut. The covariance recursion (P, S, K) does not
33	  %    depend on the measurements: the gain used at step k+1 and the posterior
34	  %    P_{k+1} are a deterministic function of the posterior P_k alone. After
35	  %    each step, the bits of P are compared with the posteriors of the last
36	  %    MAXPERIOD steps. Once P_k is bit-for-bit equal to P_{k-L}, every later
37	  %    gain repeats the last L gains exactly, so only the state update is
38	  %    computed from then on (with the same operations, in the same order).
39	  %    Typical filters reach such a cycle within a few hundred steps. If no
40	  %    cycle is found, every step is computed in full.
41	  %
42	  % For m == 2, S is inverted in closed form exactly as in the original. For any
43	  % other measurement dimension (which the original does not support), K is
44	  % obtained by solving against S.
45	
46	  MAXPERIOD = 64;
47	
48	  F = model.F; Q = model.Q; H = model.H; R = model.R;
49	  x = model.x0(:); P = model.P0;
50	
51	  N = size(Z, 1);
52	  n = numel(x);
53	  m = size(H, 1);
54	  X = zeros(N, n);
55	
56	  Ft = F.';
57	  Ht = H.';
58	  I  = eye(n);
59	  Zt = Z(:, 1:m).';                      % m x N, one column per step
60	  zn1 = zeros(n, 1); znn = zeros(n, n);
61	  zm1 = zeros(m, 1); zmm = zeros(m, m); znm = zeros(n, m);
62	
63	  % Ring buffer of the posterior-P bit patterns and gains of recent steps.
64	  nslot = MAXPERIOD + 1;
65	  Pbits = zeros(n * n, nslot, 'uint64');
66	  Kbuf  = zeros(n, m, nslot);
67	  slotstep = zeros(1, nslot);            % step stored in each slot (0 = empty)
68	
69	  % --- full steps, until the covariance recursion becomes periodic ---------
70	  k = 0;
71	  period = 0;
72	  while k < N
73	    k = k + 1;
74	
75	    % --- predict ---
76	    % x = F x
77	    xp = zn1;
78	    for p = 1:n, xp = xp + F(:, p) .* x(p); end
79	    x = xp;
80	    % P = (F P) F' + Q
81	    FP = znn;
82	    for p = 1:n, FP = FP + F(:, p) .* P(p, :); end
83	    P = znn;
84	    for p = 1:n, P = P + FP(:, p) .* Ft(p, :); end
85	    P = P + Q;
86	
87	    % --- update ---
88	    % PHt = P H'                           n x m
89	    PHt = znm;
90	    for p = 1:n, PHt = PHt + P(:, p) .* Ht(p, :); end
91	    % S = H PHt + R                        m x m
92	    S = zmm;
93	    for p = 1:n, S = S + H(:, p) .* PHt(p, :); end
94	    S = S + R;
95	    % K = PHt inv(S)                       n x m
96	    if m == 2
97	      d    = S(1, 1) * S(2, 2) - S(1, 2) * S(2, 1);
98	      Sinv = [S(2, 2) / d, -S(1, 2) / d; -S(2, 1) / d, S(1, 1) / d];
99	      K = znm;
100	      for p = 1:m, K = K + PHt(:, p) .* Sinv(p, :); end
101	    else
102	      K = PHt / S;
103	    end
104	    % y = z - H x                          m x 1
105	    Hx = zm1;
106	    for p = 1:n, Hx = Hx + H(:, p) .* x(p); end
107	    y = Zt(:, k) - Hx;
108	    % x = x + K y
109	    Ky = zn1;
110	    for p = 1:m, Ky = Ky + K(:, p) .* y(p); end
111	    x = x + Ky;
112	    % P = (I - K H) P
113	    KH = znn;
114	    for p = 1:m, KH = KH + K(:, p) .* H(p, :); end
115	    IKH = I - KH;
116	    Pn = znn;
117	    for p = 1:n, Pn = Pn + IKH(:, p) .* P(p, :); end
118	    P = Pn;
119	
120	    X(k, :) = x.';
121	
122	    % --- look for P_k equal (bitwise) to an earlier posterior P_{k-L} -------
123	    bits = typecast(P(:), 'uint64');
124	    slot = mod(k - 1, nslot) + 1;
125	    if all(isfinite(P(:)))
126	      hit = find(slotstep > 0 & all(Pbits == bits, 1), 1);
127	      if ~isempty(hit)
128	        period = k - slotstep(hit);
129	      end
130	    end
131	    Pbits(:, slot) = bits;
132	    Kbuf(:, :, slot) = K;
133	    slotstep(slot) = k;
134	    if period > 0
135	      break
136	    end
137	  end
138	
139	  if period == 0
140	    return                               % reached N without a cycle
141	  end
142	
143	  % Gains for the steps after k repeat those of steps k-period+1 .. k.
144	  Kcyc = zeros(n, m, period);
145	  for j = 1:period
146	    Kcyc(:, :, j) = Kbuf(:, :, mod(k - period + j - 1, nslot) + 1);
147	  end
148	
149	  % --- state-only steps, same operations and order as above ----------------
150	  j = 0;
151	  for k = k + 1:N
152	    j = j + 1;
153	    if j > period, j = 1; end
154	    K = Kcyc(:, :, j);
155	
156	    xp = zn1;
157	    for p = 1:n, xp = xp + F(:, p) .* x(p); end
158	    Hx = zm1;
159	    for p = 1:n, Hx = Hx + H(:, p) .* xp(p); end
160	    y = Zt(:, k) - Hx;
161	    Ky = zn1;
162	    for p = 1:m, Ky = Ky + K(:, p) .* y(p); end
163	    x = xp + Ky;
164	
165	    X(k, :) = x.';
166	  end
167	end
